args.command:
cd /bench/repo && cat > /tmp/ents.pl <<'EOF'
use strict; use warnings;
my @all = do { open my $f,'<','/tmp/all_files.txt'; map { chomp; $_ } <$f> };
my @types = qw(User Memo Attachment Reaction Inbox MemoRelation MemoShare IdentityProvider UserSetting UserIdentity InstanceSetting);
my %pkgs; my %counts;
for my $p (@all) {
  next if $p =~ m{^store/};          # exclude the data layer itself
  next if $p =~ m{^proto/gen/};      # generated protobufs
  open my $fh,'<',$p or next; local $/; my $c=<$fh>;
  my ($dir) = $p =~ m{^(.*)/[^/]+$}; $dir //= '.';
  for my $t (@types) {
    my $n = () = $c =~ /(?<![\w.])store\.\Q$t\E\b/g;
    if ($n>0) { $pkgs{$t}{$dir}+=$n; $counts{$t}+=$n; }
  }
}
for my $t (sort { (scalar keys %{$pkgs{$b}//{}}) <=> (scalar keys %{$pkgs{$a}//{}}) || ($counts{$b}//0) <=> ($counts{$a}//0) } @types) {
  my $np = scalar keys %{$pkgs{$t}//{}};
  printf "%-18s packages=%-3d refs=%-4d  %s\n", $t, $np, $counts{$t}//0, join(', ', map { "$_(".$pkgs{$t}{$_}.")" } sort { $pkgs{$t}{$b} <=> $pkgs{$t}{$a} } keys %{$pkgs{$t}//{}});
}
EOF
perl /tmp/ents.pl
